/*  The benchmark, as generated by site/build_data.py from
 *  benchmark/data/corpus.jsonl. Every count on the page is read from here.
 */
import { corpusGlobal } from "../engine/bridge";
import type { CorpusRecord } from "../engine/types";

let _corpus: CorpusRecord[] | null = null;

export function corpus(): CorpusRecord[] {
  if (_corpus) return _corpus;
  const c = corpusGlobal();
  if (!Array.isArray(c) || !c.length) {
    throw new Error("Corpus data failed to load. Run `python site/build_data.py`, then reload.");
  }
  _corpus = c as CorpusRecord[];
  return _corpus;
}

/** Instances carrying gold branch structure -- the denominator of PR/SR/HCR/SCR. */
export const annotated = (): CorpusRecord[] => corpus().filter(r => (r.b || []).length > 0);

/** Instances with at least two branches: the ones a relation can be derived for. */
export const branchy = (): CorpusRecord[] => corpus().filter(r => (r.b || []).length >= 2);

export const byId = (id: string): CorpusRecord | undefined => corpus().find(r => r.id === id);

export function countBy<K extends keyof CorpusRecord>(key: K, rows: CorpusRecord[] = corpus()): Record<string, number> {
  const m: Record<string, number> = {};
  for (const r of rows) {
    const v = r[key];
    if (v !== null && v !== undefined && v !== "") m[String(v)] = (m[String(v)] || 0) + 1;
  }
  return m;
}

export const goldBranchCount = (): number => corpus().reduce((s, r) => s + (r.b || []).length, 0);

/** The record the story is told around: a real constructed-tier instance. */
export const PROTAGONIST_ID = "wp1_fin_imp_001";
